import { useState } from 'react';

export function ItemList() {
  const [items, setItems] = useState([
    { id: 1, name: 'Item 1' },
    { id: 2, name: 'Item 2' }
  ]);
  const [deleteId, setDeleteId] = useState(null);

  const handleDelete = (id) => {
    setItems(items.filter(item => item.id !== id));
    setDeleteId(null);
  };

  return (
    <>
      <ul>
        {items.map(item => (
          <li key={item.id}>
            {item.name}
            <button onClick={() => setDeleteId(item.id)}>Delete</button>
          </li>
        ))}
      </ul>

      {deleteId && (
        <div style={modalOverlay}>
          <div style={modalBox}>
            <p>Are you sure you want to delete this item?</p>
            <button onClick={() => handleDelete(deleteId)}>Delete</button>
            <button onClick={() => setDeleteId(null)}>Cancel</button>
          </div>
        </div>
      )}
    </>
  );
}

const modalOverlay = {
  position: 'fixed',
  top: 0,
  left: 0,
  right: 0,
  bottom: 0,
  background: 'rgba(0, 0, 0, 0.5)',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center'
};

const modalBox = {
  background: 'white',
  padding: '20px',
  borderRadius: '8px',
  minWidth: '300px',
  textAlign: 'center'
};
```

Flow: delete button → stores item ID in state → modal renders → confirm deletes item and clears state, cancel hides modal.

Vanilla JS alternative if you need no framework:
```html
<ul id="list"></ul>
<div id="modal" hidden>
  <p>Sure?</p>
  <button id="confirm">Delete</button>
  <button id="cancel">Cancel</button>
</div>

<script>
let deleteId;
document.getElementById('confirm').onclick = () => {
  document.querySelector(`li[data-id="${deleteId}"]`).remove();
  document.getElementById('modal').hidden = true;
};
document.getElementById('cancel').onclick = () => {
  document.getElementById('modal').hidden = true;
};
</script>
```

React version handles state cleanly; vanilla JS works with minimal setup. Pick based on your stack.
